#!/usr/bin/env python3
"""Exercise the original-layout ROM multi-shot implementation with behavioral fixtures."""
import argparse
from pathlib import Path
import os
import subprocess
import tempfile
ROOT=Path(__file__).resolve().parents[1]
HARNESS="#include <stdio.h>\n#include <string.h>\n#include \"multilock_abi.h\"\nRomActor gActors[ML_ACTORS]; RomItem gItems[ML_ITEMS]; RomShot gPlayerShots[ML_SHOTS];\nstatic FlightPad press,hold;\nFlightPad *gInputPress=&press,*gInputHold=&hold;\nstatic union { uint64_t align; uint8_t bytes[0x600]; } player;\nvoid *gPlayer=player.bytes;\nint32_t gCurrentLevel,gVersusMode,gGameFrameCount,gGameState,gLevelMode,gCamCount;\nint32_t gChargeTimers[4],gBombCount[4],gLaserStrength[4];\nuint16_t gControllerRumbleTimers[4];\nfloat gPathProgress,gDefaultSfxSource[3],gDefaultMod;\nFlightVec3 sLockOnPos;\nint8_t gDefaultReverb;\nstatic float randomValue;\nstatic int fallbackFind,fallbackCan,fallbackUpdate;\nvoid Original_ActorInitialize(RomActor *a){memset(a,0,sizeof(*a));}\nvoid Original_ItemInitialize(RomItem *i){memset(i,0,sizeof(*i));}\nvoid Original_ShotInitialize(RomShot *s){memset(s,0,sizeof(*s));}\nint Original_FindLockTarget(RomShot *s){fallbackFind++;return 17;}\nint Original_CanLockOn(int p){fallbackCan++;return 19;}\nint Original_UpdateLockOn(void *p){fallbackUpdate++;return 23;}\nvoid Original_ClearObjects(void){}\nvoid FlightBounds_Reset(void){}\nvoid Original_PlayerDown(void *p){}\nvoid Original_CutscenePlayerDown(void *p){}\nvoid Object_SetInfo(RomInfo *i,uint32_t id){}\nfloat Rand_ZeroOne(void){return randomValue;}\nvoid Object_Kill(RomObject *o,float *s){o->status=0;}\nvoid Object_PlayerSfx(float *s,uint32_t id,int p){}\nvoid Audio_PlaySfx(uint32_t id,float *s,uint8_t t,float *f,float *v,int8_t *r){}\nvoid Audio_InitBombSfx(uint8_t p,uint8_t k){}\nvoid Audio_PlayBombFlightSfx(uint8_t p,float *s){}\nstatic void setup(RomShot *s,int id){\n Multi_ShotInitialized(s);s->obj.status=1;s->obj.id=id;s->source=0;s->noTarget=0;s->scale=1;\n}\nvoid Player_SetupArwingShot(void *p,RomShot *s,float x,float y,int id,float speed){setup(s,id);}\nvoid Player_SetupTankShot(void *p,RomShot *s,int id,float speed){setup(s,id);}\n#define CHECK(c) do{if(!(c)){fprintf(stderr,\"%s:%d: %s\\n\",__func__,__LINE__,#c);return 0;}}while(0)\nstatic void reset(void){\n memset(gActors,0,sizeof(gActors));memset(gItems,0,sizeof(gItems));memset(gPlayerShots,0,sizeof(gPlayerShots));\n memset(&gMultiState,0,sizeof(gMultiState));memset(player.bytes,0,sizeof(player.bytes));\n memset(gChargeTimers,0,sizeof(gChargeTimers));memset(gBombCount,0,sizeof(gBombCount));\n memset(gLaserStrength,0,sizeof(gLaserStrength));memset(&press,0,sizeof(press));memset(&hold,0,sizeof(hold));\n gMultiState.magic=0x4d4c4f43;gMultiState.capacity=1;gCamCount=1;\n gCurrentLevel=gVersusMode=gGameFrameCount=gGameState=gLevelMode=0;\n randomValue=0;fallbackFind=fallbackCan=fallbackUpdate=0;\n}\nstatic void actor(int i,float x){\n Multi_ActorInitialized(&gActors[i]);gActors[i].obj.status=2;\n gActors[i].info.targetOffset=20;gActors[i].obj.pos.x=x;\n}\nstatic int lock(int i){\n RomShot search={0};search.source=0;search.obj.pos=gActors[i].obj.pos;search.obj.pos.y+=20;\n return Multi_FindLockTarget(&search);\n}\nstatic void upgrade(void){\n Multi_ItemInitialized(&gItems[0]);gItems[0].obj.id=324;randomValue=0;\n Multi_ConvertDrop(&gItems[0]);Multi_CollectBomb(&gItems[0]);\n}\nstatic void three(void){\n upgrade();upgrade();actor(0,0);actor(1,1000);actor(2,2000);lock(0);lock(1);lock(2);\n}\nstatic int baseline(void){\n reset();CHECK(!Multi_Enabled(0));CHECK(Multi_CanLockOn(0)==19);\n CHECK(Multi_FindLockTarget(&gPlayerShots[0])==17);CHECK(Multi_UpdateLockOn(gPlayer)==23);\n CHECK(fallbackCan==1&&fallbackFind==1&&fallbackUpdate==1);return 1;\n}\nstatic int drops(void){\n reset();Multi_ItemInitialized(&gItems[0]);gItems[0].obj.id=324;randomValue=.19999f;\n Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==327&&Multi_ItemIsUpgrade(&gItems[0]));\n Multi_ItemInitialized(&gItems[0]);gItems[0].obj.id=324;randomValue=.2f;\n Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==324&&!Multi_ItemIsUpgrade(&gItems[0]));\n gItems[0].obj.id=322;gLaserStrength[0]=1;Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==322);\n gLaserStrength[0]=2;Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==327&&Multi_ItemIsUpgrade(&gItems[0]));\n int *excluded[]={&gCurrentLevel,&gCurrentLevel,&gLevelMode,&gVersusMode,&gCamCount};\n int values[]={13,10,2,1,2};\n for(int i=0;i<5;i++){reset();*excluded[i]=values[i];gItems[0].obj.id=324;\n  Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==324);}\n reset();PI(gPlayer,P_FORM)=2;gItems[0].obj.id=324;Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==324);\n reset();gMultiState.capacity=3;gItems[0].obj.id=324;Multi_ConvertDrop(&gItems[0]);CHECK(gItems[0].obj.id==324);\n return 1;\n}\nstatic int pickups(void){\n reset();gBombCount[0]=4;upgrade();CHECK(gMultiState.capacity==2&&gBombCount[0]==4);\n upgrade();CHECK(gMultiState.capacity==3&&gBombCount[0]==4);\n Multi_ItemInitialized(&gItems[1]);Multi_CollectBomb(&gItems[1]);CHECK(gBombCount[0]==5);\n Multi_ItemInitialized(&gItems[0]);CHECK(!Multi_ItemIsUpgrade(&gItems[0]));\n Multi_CollectBomb(&gItems[0]);CHECK(gBombCount[0]==6);return 1;\n}\nstatic int acquisition(void){\n reset();upgrade();upgrade();actor(0,0);actor(1,1000);actor(2,2000);actor(3,3000);\n CHECK(lock(0)==1&&lock(1)==1&&lock(2)==1&&lock(3)==0);\n int targets[3];CHECK(Multi_GetTargets(targets)==3&&targets[0]==0&&targets[1]==1&&targets[2]==2);\n uint32_t gen=gMultiState.actorGeneration[1];Multi_ActorInitialized(&gActors[1]);\n CHECK(gMultiState.actorGeneration[1]!=gen);CHECK(Multi_GetTargets(targets)==2&&targets[0]==0&&targets[1]==2);\n return 1;\n}\nstatic int migration(void){\n reset();actor(0,0);gActors[0].lockTimers[0]=20;setup(&gPlayerShots[3],8);upgrade();\n CHECK(Multi_IsOwnedShot(&gPlayerShots[3])&&Multi_SelectShotTarget(&gPlayerShots[3])==1);\n CHECK(sLockOnPos.x==0&&Multi_GetTargets(0)==0);\n Multi_ShotInitialized(&gPlayerShots[3]);CHECK(!Multi_IsOwnedShot(&gPlayerShots[3]));\n reset();actor(0,0);gActors[0].lockTimers[0]=20;upgrade();\n CHECK(Multi_GetTargets(0)==1&&gChargeTimers[0]==21);return 1;\n}\nstatic int volley(void){\n reset();three();CHECK(gMultiState.lockCount==3);\n for(int i=0;i<15;i++){gPlayerShots[i].obj.status=1;gPlayerShots[i].obj.id=9;}\n gPlayerShots[2].obj.status=0;gPlayerShots[7].obj.id=4;gPlayerShots[7].source=0;\n gPlayerShots[14].obj.status=0;press.button=0x8000;\n CHECK(Multi_UpdateLockOn(gPlayer)==1&&gMultiState.volleys==1);\n int slots[]={2,7,14};\n for(int i=0;i<3;i++){CHECK(Multi_IsOwnedShot(&gPlayerShots[slots[i]]));\n  CHECK(Multi_SelectShotTarget(&gPlayerShots[slots[i]])==1);\n  CHECK(sLockOnPos.x==(float)(i*1000)&&sLockOnPos.y==20);}\n CHECK(gMultiState.lockCount==0&&!gPlayerShots[15].obj.status);\n Multi_ActorInitialized(&gActors[1]);CHECK(Multi_SelectShotTarget(&gPlayerShots[7])==0);\n CHECK(Multi_SelectShotTarget(&gPlayerShots[2])==1&&Multi_SelectShotTarget(&gPlayerShots[14])==1);return 1;\n}\nstatic int volley_full(void){\n reset();three();for(int i=0;i<15;i++){gPlayerShots[i].obj.status=1;gPlayerShots[i].obj.id=9;}\n gPlayerShots[1].obj.status=0;gPlayerShots[2].obj.id=4;gPlayerShots[2].source=0;\n press.button=0x8000;Multi_UpdateLockOn(gPlayer);\n CHECK(!gMultiState.volleys&&gMultiState.lockCount==3);\n CHECK(!gPlayerShots[1].obj.status&&gPlayerShots[2].obj.status==1&&gPlayerShots[2].obj.id==4);\n CHECK(gActors[0].lockTimers[0]&&gActors[1].lockTimers[0]&&gActors[2].lockTimers[0]);return 1;\n}\nstatic int bomb(void){\n reset();three();gBombCount[0]=2;press.button=0x4000;\n CHECK(Multi_UpdateLockOn(gPlayer)==1&&gBombCount[0]==1&&gMultiState.bombs==1);\n CHECK(Multi_IsOwnedShot(&gPlayerShots[15])&&Multi_SelectShotTarget(&gPlayerShots[15])==1);\n CHECK(sLockOnPos.x==2000&&!gMultiState.lockCount);\n reset();three();gBombCount[0]=1;gPlayerShots[15].obj.status=1;press.button=0x4000;Multi_UpdateLockOn(gPlayer);\n CHECK(gBombCount[0]==1&&gMultiState.lockCount==3&&!gMultiState.bombs);\n gPlayerShots[15].obj.status=0;gBombCount[0]=0;Multi_UpdateLockOn(gPlayer);\n CHECK(gMultiState.lockCount==3&&!gMultiState.bombs&&!gPlayerShots[15].obj.status);return 1;\n}\nstatic int lifecycle(void){\n reset();three();gGameState=4;Multi_ClearObjects();CHECK(gMultiState.capacity==3&&!gMultiState.lockCount);\n gGameState=3;Multi_ClearObjects();CHECK(gMultiState.capacity==1);\n upgrade();Multi_PlayerDown(gPlayer);CHECK(gMultiState.capacity==1);\n upgrade();Multi_PlayerDownUpdate(gPlayer);CHECK(gMultiState.capacity==1);\n void *old=gPlayer;gPlayer=0;Multi_ClearObjects();gPlayer=old;return 1;\n}\nint main(void){\n struct{const char*name;int(*run)(void);}tests[]={\n  {\"baseline\",baseline},{\"drops\",drops},{\"pickups\",pickups},{\"acquisition\",acquisition},\n  {\"migration\",migration},{\"volley\",volley},{\"volley_full\",volley_full},{\"bomb\",bomb},{\"lifecycle\",lifecycle}};\n unsigned passed=0;printf(\"{\\\"tests\\\":{\");\n for(unsigned i=0;i<sizeof(tests)/sizeof(*tests);i++){\n  int ok=tests[i].run();passed+=ok;printf(\"%s\\\"%s\\\":%s\",i?\",\":\"\",tests[i].name,ok?\"true\":\"false\");}\n printf(\"},\\\"passed\\\":%u,\\\"total\\\":%zu}\\n\",passed,sizeof(tests)/sizeof(*tests));\n return passed==sizeof(tests)/sizeof(*tests)?0:1;\n}"
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--build-dir",type=Path,default=ROOT/"build/multishot-tests")
    args=parser.parse_args()
    args.build_dir.mkdir(parents=True,exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="case-",dir=args.build_dir) as name:
        temp=Path(name)
        source=temp/"harness.c"
        source.write_text(HARNESS)
        binary=temp/"harness"
        env=dict(os.environ,TMPDIR=str(temp))
        subprocess.run(["cc","-std=gnu17","-Wall","-Wextra","-Werror","-Wno-unused-parameter",
                        "-I",str(ROOT/"tools/n64"),str(source),str(ROOT/"tools/n64/multilock.c"),
                        "-o",str(binary)],check=True,env=env)
        return subprocess.run([str(binary)],check=False,env=env).returncode
if __name__=="__main__":
    raise SystemExit(main())
